228	    let mut tokens = s.split_whitespace();
229	    tokens.next()?; // the @implements / @verifies marker itself
230	    let req_id = tokens.next()?.to_string();
231	    let version = tokens.next()?.strip_prefix('v')?.parse::<u32>().ok()?;
232	    let hash = tokens.next()?.to_string();
