270	/// [`scan_annotations`] across the project (annotations for other
271	/// requirements are ignored).
272	pub fn trace_state(req: &Requirement, annotations: &[Annotation]) -> TraceState {
273	    let find = |kind: AnnotationKind| {
274	        annotations
275	            .iter()
276	            .find(|a| a.kind == kind && a.req_id == req.id)
277	    };
278	
279	    let links = [
280	        find(AnnotationKind::Addresses),
281	        find(AnnotationKind::Implements),
282	        find(AnnotationKind::Verifies),
283	    ];
284	
285	    let present: Vec<&Annotation> = links.into_iter().flatten().collect();
