289	    }
290	    if present.len() < 3 {
291	        return TraceState::Incomplete;
292	    }
293	    if present.iter().any(|a| a.hash != req.hash) {
294	        return TraceState::Stale;
295	    }
296	    TraceState::Traced
297	}
