#[test]
fn no_links_is_orphaned() {
    let req = requirement("REQ-001", &current_hash());

    assert_eq!(trace_state(&req, &[]), TraceState::Orphaned);
}

#[test]
fn missing_a_link_is_incomplete() {
    let hash = current_hash();
    let req = requirement("REQ-001", &hash);
    let annotations = vec![
